WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/39.0/connection.js")} 
{!REQUIRESCRIPT("/support/console/39.0/integration.js")} 

var pageUrl = '{!URLFOR($Action.Activity.LogCall)}'; 
var parameters = '?title=Call&what_id={!Account.Id}'; 
var noHeader = '&isdtp=vw'; 
var url = "/00T/e?title=Call&what_id={!Account.Id}&followup=1&tsk5=Call&retURL=/{!Account.Id}&isdtp=vw"; 
var link = pageUrl + parameters; 

if (sforce.console.isInConsole()) 
{ 
   window.open(url, 'Window Name', 'target: _blank'); 
   console.log('in console' + url);
} 
else { 
    window.open(link+ '&isdtp=vw', 'Window Name', 'target: _blank'); 
    console.log('in standard view: ' + link + '&isdtp=vw'); 
}
